// Data-driven figure renderers. Chapters embed them with
//   <!-- @fig name [arg] -->
// Every value shown comes from /data (generated by generate-data.mjs).
import { readFileSync } from 'node:fs';

const load = (n) => JSON.parse(readFileSync(new URL(`../data/${n}.json`, import.meta.url), 'utf8'));
const palette = load('palette');
const hslOk = load('hsl-vs-oklch');
const semantic = load('semantic-colors');
const matrix = load('contrast-matrix');
const type = load('type-scales');
const dtcg = load('tokens.dtcg');
const eco = load('economics');
const usd = (n) => (n < 0 ? '−' : '') + '$' + Math.abs(Math.round(n)).toLocaleString('en-US');
const pct = (n) => Math.round(n * 100) + '%';

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const ink = '#0b0d12';
// Pick the label colour with the higher contrast against the chip.
const labelOn = (s) => (s.onWhite >= s.onBlack ? '#ffffff' : ink);
const ramp = (name) => palette.ramps.find((r) => r.name === name);
const step = (name, st) => ramp(name).steps.find((s) => s.step === Number(st));
const fmtL = (s) => `${s.l.toFixed(3).replace(/^0/, '')} ${s.c.toFixed(3).replace(/^0/, '')} ${s.h}`;

const figures = {
  // Full palette: every ramp, every step, with contrast on white.
  ramps() {
    const head = `<div class="ramp-head"><span></span>${palette.ramps[0].steps.map((s) => `<span>${s.step}</span>`).join('')}</div>`;
    const rows = palette.ramps.map((r) => `<div class="ramp-row"><div class="rn"><b>${r.name}</b>h ${r.hue}°</div>${r.steps.map((s) => {
      const c = labelOn(s);
      return `<div class="chip${s.clipped ? ' clipped' : ''}" style="background:${s.hex};color:${c}" title="${r.name}.${s.step} · ${s.oklch} · ${s.hex} · ${s.onWhite}:1 on white"><span class="st">${s.step}</span><span><span class="hx">${s.hex.slice(1)}</span><br><span class="cr">${s.onWhite >= 4.5 ? '●' : s.onWhite >= 3 ? '◐' : '○'} ${s.onWhite}</span></span></div>`;
    }).join('')}</div>`).join('');
    return `<div class="ramps">${head}${rows}</div>
      <p class="fig-label" style="margin:14px 0 0">● ≥ 4.5:1 on white (body text) &nbsp; ◐ ≥ 3:1 (large text, UI) &nbsp; ○ &lt; 3:1 (surfaces, decoration) &nbsp; ◦ ring = chroma reduced to fit sRGB</p>`;
  },

  // One ramp in detail with full OKLCH values.
  'ramp-detail'(name = 'brand') {
    const r = ramp(name);
    return `<div class="ramp-detail">${r.steps.map((s) => `<div style="background:${s.hex};color:${labelOn(s)}"><span class="st">${s.step}</span><span>L ${s.l.toFixed(3)}<br>C ${s.c.toFixed(3)}<br>H ${s.h}<span class="ok">${s.hex}</span>${s.onWhite}:1</span></div>`).join('')}</div>`;
  },

  // HSL "lightness 50%" vs OKLCH "L 0.65" — with grayscale strip showing perceived lightness.
  'hsl-vs-oklch'() {
    const row = (items, title, note) => `<p class="row-label">${title}<span>${note}</span></p><div class="swrow">${items.map((i) => {
      const g = Math.round(i.perceivedL * 100);
      return `<div><div class="sw-big" style="background:${i.hex};color:${i.onWhite > 3 ? '#fff' : ink}">${i.hex}</div><div class="sw-gray" style="background:oklch(${i.perceivedL} 0 0)" title="Perceived lightness ${i.perceivedL}"></div><div class="sw-meta">${esc(i.label)}<br>perceived L ${i.perceivedL.toFixed(2)} · ${i.onWhite}:1</div></div>`;
    }).join('')}</div>`;
    return row(hslOk.hsl, 'HSL — every swatch says "lightness 50%"', 'grey strip = what the eye actually sees')
      + '<div style="height:26px"></div>'
      + row(hslOk.oklch, 'OKLCH — every swatch says "L 0.65"', 'grey strips match');
  },

  // Line chart: contrast against white for each hue, by step. Lines nearly coincide.
  'contrast-chart'() {
    const W = 760, H = 300, m = { l: 44, r: 92, t: 18, b: 34 };
    const iw = W - m.l - m.r, ih = H - m.t - m.b;
    const steps = palette.ramps[0].steps.map((s) => s.step);
    const x = (i) => m.l + (i / (steps.length - 1)) * iw;
    const ymax = 17;
    const y = (v) => m.t + ih - ((v - 1) / (ymax - 1)) * ih;
    const grid = [1, 3, 4.5, 7, 10, 13, 16].map((v) => `<line x1="${m.l}" x2="${m.l + iw}" y1="${y(v)}" y2="${y(v)}" stroke="currentColor" stroke-opacity="${v === 4.5 || v === 3 ? 0.55 : 0.12}" stroke-dasharray="${v === 4.5 || v === 3 ? '4 3' : ''}"/><text x="${m.l - 8}" y="${y(v) + 3.5}" text-anchor="end" font-size="10" fill="currentColor" fill-opacity="0.6">${v}</text>`).join('');
    const thr = `<text x="${m.l + iw + 8}" y="${y(4.5) + 3.5}" font-size="10" fill="currentColor">4.5:1 text</text><text x="${m.l + iw + 8}" y="${y(3) + 3.5}" font-size="10" fill="currentColor" fill-opacity="0.75">3:1 UI</text>`;
    const xl = steps.map((s, i) => `<text x="${x(i)}" y="${H - 12}" text-anchor="middle" font-size="10" fill="currentColor" fill-opacity="0.6">${s}</text>`).join('');
    const lines = palette.ramps.map((r) => {
      const col = r.steps[6].hex;
      const pts = r.steps.map((s, i) => `${x(i).toFixed(1)},${y(s.onWhite).toFixed(1)}`).join(' ');
      const dots = r.steps.map((s, i) => `<circle cx="${x(i)}" cy="${y(s.onWhite)}" r="3" fill="${col}" stroke="var(--bg-raised)" stroke-width="1.5"><title>${r.name}.${s.step}: ${s.onWhite}:1 on white</title></circle>`).join('');
      return `<polyline points="${pts}" fill="none" stroke="${col}" stroke-width="2" stroke-linejoin="round"/>${dots}`;
    }).join('');
    const legend = palette.ramps.map((r) => `<span style="display:inline-flex;align-items:center;gap:6px;margin-right:14px"><i style="width:14px;height:2px;background:${r.steps[6].hex};display:inline-block"></i>${r.name}</span>`).join('');
    return `<p class="fig-label" style="margin:0 0 8px">Contrast ratio against white, by ramp step</p><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Contrast against white by step for six hues; the lines nearly coincide" style="width:100%;height:auto;color:var(--text)">${grid}${thr}${xl}${lines}<text x="${m.l}" y="${H - 1}" font-size="10" fill="currentColor" fill-opacity="0.6">ramp step →</text></svg><div class="fig-label" style="margin-top:6px;text-transform:none;letter-spacing:0">${legend}</div>`;
  },

  // Neutral contrast matrix.
  'contrast-matrix'() {
    const steps = matrix.steps;
    const cls = (v) => (v >= 7 ? ['AAA', '#0b0d12', '#fff'] : v >= 4.5 ? ['AA', '#3d4350', '#fff'] : v >= 3 ? ['3:1', '#c9ccd2', '#0b0d12'] : ['', 'transparent', 'var(--text-faint)']);
    const head = `<tr><th></th>${steps.map((s) => `<th class="num" style="text-align:center">${s}</th>`).join('')}</tr>`;
    const rows = steps.map((a, i) => `<tr><th class="num" style="text-align:left">${a}</th>${steps.map((b, j) => {
      const v = matrix.neutral[i][j]; const [, bg, fg] = cls(v);
      return `<td class="num" style="text-align:center;background:${i === j ? 'var(--bg-sunken)' : bg};color:${fg};padding:6px 2px;border:1px solid var(--bg-raised)">${i === j ? '—' : v.toFixed(1)}</td>`;
    }).join('')}</tr>`).join('');
    return `<div class="table-wrap" style="margin:0"><table class="compact" style="table-layout:fixed"><thead>${head}</thead><tbody>${rows}</tbody></table></div>
      <p class="fig-label" style="margin:12px 0 0"><span class="sw" style="background:#0b0d12"></span>≥ 7:1 (AAA text) &nbsp; <span class="sw" style="background:#3d4350"></span>≥ 4.5:1 (AA text) &nbsp; <span class="sw" style="background:#c9ccd2"></span>≥ 3:1 (large text, UI boundaries) &nbsp; blank &lt; 3:1</p>`;
  },

  // Semantic token table, light and dark.
  'semantic-table'() {
    const rows = semantic.tokens.map((t) => `<tr><td><code>color.${t.token}</code></td><td><span class="sw" style="background:${t.lightHex}"></span><span class="tk prim">${t.light}</span></td><td><span class="sw" style="background:${t.darkHex}"></span><span class="tk prim">${t.dark}</span></td></tr>`).join('');
    return `<div class="table-wrap" style="margin:0"><table class="compact"><thead><tr><th>Semantic token</th><th>Light theme →</th><th>Dark theme →</th></tr></thead><tbody>${rows}</tbody></table></div>`;
  },

  'contrast-pairs'() {
    const badge = (v, min, pass) => (min === 0 ? `<span class="num">${v}</span>` : `${v} <span class="${pass ? 'pass' : 'fail'}">${pass ? 'pass' : 'fail'}</span>`);
    const rows = semantic.pairs.map((p) => `<tr><td>${p.use}</td><td><code>${p.fg}</code><br><span class="muted">on <code>${p.bg}</code></span></td><td class="num">${p.min ? p.min + ':1' : 'exempt'}</td><td class="num">${badge(p.light, p.min, p.lightPass)}</td><td class="num">${badge(p.dark, p.min, p.darkPass)}</td></tr>`).join('');
    return `<div class="table-wrap" style="margin:0"><table class="compact"><thead><tr><th>Use</th><th>Pairing</th><th class="num">WCAG min</th><th class="num">Light</th><th class="num">Dark</th></tr></thead><tbody>${rows}</tbody></table></div>`;
  },

  // The same mini UI rendered from the same semantic tokens in both themes.
  'theme-preview'() {
    const T = Object.fromEntries(semantic.tokens.map((t) => [t.token, t]));
    const card = (th) => {
      const v = (k) => T[k][th + 'Hex'];
      return `<div style="background:${v('bg.canvas')};color:${v('text.primary')};border:1px solid ${v('border.default')};border-radius:12px;padding:18px;font-size:13px;line-height:1.45">
        <div style="font-family:var(--font-mono);font-size:10px;letter-spacing:.05em;text-transform:uppercase;color:${v('text.secondary')};margin-bottom:10px">${th} theme</div>
        <div style="font-weight:650;font-size:16px;margin-bottom:4px">Invoice #2041</div>
        <div style="color:${v('text.secondary')};margin-bottom:12px">Due 14 Dec · <span style="color:${v('text.link')};text-decoration:underline">View customer</span></div>
        <div style="background:${v('bg.subtle')};border-radius:8px;padding:10px;margin-bottom:12px;display:flex;justify-content:space-between"><span>Amount</span><b>₹ 84,200</b></div>
        <div style="background:${v('feedback.danger.bg')};color:${v('feedback.danger.text')};border-radius:6px;padding:7px 10px;margin-bottom:12px;font-size:12px">Payment failed: card declined</div>
        <div style="display:flex;gap:8px"><span style="background:${v('action.primary.bg')};color:${v('action.primary.text')};padding:7px 12px;border-radius:6px;font-weight:600">Retry payment</span><span style="border:1px solid ${v('border.strong')};padding:6px 12px;border-radius:6px">Cancel</span></div></div>`;
    };
    return `<div class="cols-2">${card('light')}${card('dark')}</div>`;
  },

  // Modular scales compared as bars.
  'type-scales'() {
    const max = 16 * Math.pow(1.618, 4);
    const groups = type.scales.map((s) => `<div><p class="row-label">${s.name}<span>× ${s.ratio}</span></p><div class="scale-bars">${s.sizes.filter((z) => z.step >= -2 && z.step <= 4).reverse().map((z) => `<div class="scale-bar"><span>${z.step > 0 ? '+' : ''}${z.step}</span><span class="bar${z.step === 0 ? ' acc' : ''}" style="width:${Math.min(100, (z.px / max) * 100).toFixed(1)}%"></span><span class="v">${z.px}px</span></div>`).join('')}</div></div>`).join('');
    return `<div class="cols-2" style="gap:28px">${groups}</div>`;
  },

  // Product type scale specimen.
  'type-specimen'() {
    const sample = { display: 'Ledgerly', heading: 'Quarterly revenue', body: 'Invoices are reconciled nightly against the ledger.', label: 'Export CSV', caption: 'Updated 4 minutes ago' };
    const rows = type.productScale.map((t) => {
      const fam = t.token.split('.')[0];
      return `<div class="spec-row"><span class="tok">${t.token}</span><span class="sample" style="font-size:${t.px}px;line-height:${t.lineHeight}px;font-weight:${t.weight};letter-spacing:${t.tracking}em">${sample[fam]}</span><span class="meta">${t.px}/${t.lineHeight} · ${t.weight}${t.tracking ? ' · ' + t.tracking + 'em' : ''}</span></div>`;
    }).join('');
    return `<div class="specimen">${rows}</div>`;
  },

  'type-table'() {
    const rows = type.productScale.map((t) => `<tr><td><code>${t.token}</code></td><td class="num">${t.px}</td><td class="num">${t.lineHeight}</td><td class="num">${t.ratio}</td><td class="num">${t.weight}</td><td class="num">${t.tracking}</td></tr>`).join('');
    return `<div class="table-wrap" style="margin:0"><table class="compact"><thead><tr><th>Token</th><th class="num">Size px</th><th class="num">Line px</th><th class="num">Ratio</th><th class="num">Weight</th><th class="num">Tracking em</th></tr></thead><tbody>${rows}</tbody></table></div>`;
  },


  // Budget scenarios in FTE-months, converted at three example rates.
  'budget-scenarios'() {
    const summary = eco.scenarios.map((sc) => `<tr><th>${sc.name}<br><span class="muted" style="font-weight:400">${sc.stage}</span></th><td style="font-size:0.92em">${sc.profile}</td><td class="num">${sc.buildFteMonths.toFixed(1)}</td><td class="num">${sc.runFteMonths.toFixed(1)}</td><td class="num" style="font-weight:600">${sc.totalFteMonths.toFixed(1)}</td>${eco.rates.map((r) => `<td class="num">${usd(sc.totalFteMonths * r)}</td>`).join('')}</tr>`).join('');
    const detail = eco.scenarios.map((sc) => {
      const rows = (list, phase) => list.map(([role, fte, m], i) => `<tr><td>${i === 0 ? `<b>${sc.name}</b>` : ''}</td><td class="muted">${i === 0 ? phase : ''}</td><td>${role}</td><td class="num">${fte} FTE × ${m} mo</td><td class="num">${(fte * m).toFixed(1)}</td></tr>`).join('');
      return rows(sc.build, 'Build') + rows(sc.run, 'Run').replace(`<b>${sc.name}</b>`, '');
    }).join('');
    return `<div class="table-wrap" style="margin:0 0 20px"><table class="compact"><caption>Year-one investment</caption><thead><tr><th>Scenario</th><th>Profile</th><th class="num">Build FTE-mo</th><th class="num">Run FTE-mo</th><th class="num">Total</th>${eco.rates.map((r) => `<th class="num">@ ${usd(r)}/mo</th>`).join('')}</tr></thead><tbody>${summary}</tbody></table></div>
    <div class="table-wrap" style="margin:0"><table class="compact"><caption>How each total is built up</caption><thead><tr><th>Scenario</th><th>Phase</th><th>Role</th><th class="num">Allocation</th><th class="num">FTE-months</th></tr></thead><tbody>${detail}</tbody></table></div>`;
  },

  'roi-years'() {
    const A = eco.assumptions;
    const rows = eco.years.map((y) => `<tr><td>Year ${y.year}<br><span class="muted">${y.note}</span></td><td class="num">${pct(y.adoption)}</td><td class="num">${y.hours.toLocaleString('en-US')} h</td><td class="num">${usd(y.usd)}</td><td class="num">${usd(y.cost)}</td><td class="num" style="font-weight:600;color:${y.net < 0 ? 'var(--bad)' : 'var(--ok)'}">${usd(y.net)}</td><td class="num">${y.roi}%</td></tr>`).join('');
    return `<div class="table-wrap" style="margin:0"><table class="compact"><thead><tr><th>Year</th><th class="num">Adoption</th><th class="num">Hours saved</th><th class="num">Value</th><th class="num">Team cost</th><th class="num">Net</th><th class="num">ROI</th></tr></thead><tbody>${rows}</tbody></table></div>
    <p class="fig-label" style="margin:12px 0 0;text-transform:none;letter-spacing:0;line-height:1.6">Assumptions: ${eco.ledgerly.engineers} engineers, ${eco.ledgerly.designers} designers · ${A.hoursPerFteYear} focused h/FTE-year · ${pct(A.uiShareEng)} of engineering and ${pct(A.uiShareDes)} of design time is UI production · efficiency gain on system-covered work 20% · team of 2 FTE at ${usd(A.monthlyRate)}/FTE-month (${usd(A.hourlyRate)}/h). Excludes change-once events, accessibility remediation and quality effects.</p>`;
  },

  sensitivity() {
    const head = `<tr><th>Efficiency gain ↓ · Adoption →</th>${eco.sensitivity[0].cells.map((c) => `<th class="num">${pct(c.adoption)}</th>`).join('')}</tr>`;
    const rows = eco.sensitivity.map((r) => `<tr><th>${pct(r.gain)}${r.gain === 0.34 ? ' <span class="muted">(Figma figure)</span>' : ''}</th>${r.cells.map((c) => `<td class="num" style="background:${c.net >= 0 ? 'var(--ok-bg)' : 'var(--bad-bg)'};color:${c.net >= 0 ? 'var(--ok)' : 'var(--bad)'};font-weight:600">${usd(c.net)}</td>`).join('')}</tr>`).join('');
    return `<div class="table-wrap" style="margin:0"><table class="compact"><caption>Ledgerly — annual net value vs a 2-FTE team (${usd(eco.years[0].cost)}/yr)</caption><thead>${head}</thead><tbody>${rows}</tbody></table></div>`;
  },

  'break-even'() {
    const list = eco.breakEvens.filter((b) => b.adoption === 0.7 && b.gain === 0.2);
    const max = Math.max(...list.map((b) => b.engineers));
    const bars = list.map((b) => `<div class="hbar"><span>${b.fte} FTE team <span class="muted">· ${usd(b.cost)}/yr</span></span><div class="track"><div class="fill" style="width:${(b.engineers / max) * 100}%">${b.engineers}</div></div></div>`).join('');
    const other = eco.breakEvens.filter((b) => !(b.adoption === 0.7 && b.gain === 0.2)).map((b) => `${b.fte} FTE at ${pct(b.adoption)} adoption and ${pct(b.gain)} gain → ${b.engineers} engineers`).join(' · ');
    return `<p class="fig-label" style="margin:0 0 12px">Engineers needed for efficiency savings alone to cover the team (70% adoption, 20% gain)</p><div class="hbars">${bars}</div><p class="fig-label" style="margin:14px 0 0;text-transform:none;letter-spacing:0">Sensitivity: ${other}.</p>`;
  },


  // Coordination paths: every team agreeing with every other team vs agreeing with one shared system.
  coordination() {
    const W = 760, H = 280, m = { l: 44, r: 150, t: 16, b: 36 };
    const iw = W - m.l - m.r, ih = H - m.t - m.b, N = 16, ymax = 120;
    const x = (n) => m.l + ((n - 1) / (N - 1)) * iw, y = (v) => m.t + ih - (v / ymax) * ih;
    const pairs = Array.from({ length: N }, (_, i) => [i + 1, ((i + 1) * i) / 2]);
    const hub = Array.from({ length: N }, (_, i) => [i + 1, i + 1]);
    const grid = [0, 30, 60, 90, 120].map((v) => `<line x1="${m.l}" x2="${m.l + iw}" y1="${y(v)}" y2="${y(v)}" stroke="currentColor" stroke-opacity="${v ? 0.12 : 0.5}"/><text x="${m.l - 8}" y="${y(v) + 3.5}" font-size="10" text-anchor="end" fill="currentColor" fill-opacity=".6">${v}</text>`).join('');
    const xl = [1, 4, 8, 12, 16].map((n) => `<text x="${x(n)}" y="${H - 16}" font-size="10" text-anchor="middle" fill="currentColor" fill-opacity=".6">${n}</text>`).join('');
    const line = (pts, col) => `<polyline points="${pts.map(([n, v]) => `${x(n).toFixed(1)},${y(v).toFixed(1)}`).join(' ')}" fill="none" stroke="${col}" stroke-width="2"/>` + pts.map(([n, v]) => `<circle cx="${x(n)}" cy="${y(v)}" r="2.6" fill="${col}"><title>${n} teams: ${v}</title></circle>`).join('');
    return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Pairwise agreements grow quadratically with team count; agreements with a shared system grow linearly" style="width:100%;height:auto;color:var(--text)">${grid}${xl}
      ${line(pairs, 'var(--text)')}${line(hub, 'var(--accent)')}
      <text x="${x(16) + 10}" y="${y(120) + 4}" font-size="11" fill="currentColor">Team ↔ team: n(n−1)/2</text><text x="${x(16) + 10}" y="${y(120) + 18}" font-size="10" fill="currentColor" fill-opacity=".6">120 at 16 teams</text>
      <text x="${x(16) + 10}" y="${y(16) + 4}" font-size="11" fill="var(--accent-text)">Team ↔ system: n</text><text x="${x(16) + 10}" y="${y(16) + 18}" font-size="10" fill="currentColor" fill-opacity=".6">16 at 16 teams</text>
      <text x="${m.l}" y="${H - 1}" font-size="10" fill="currentColor" fill-opacity=".6">number of teams making UI decisions →</text></svg>`;
  },


  // Grid anatomy: columns, gutters, margins, computed from real numbers.
  'grid-anatomy'() {
    const W = 760, H = 250, margin = 32, gutter = 16, cols = 12, top = 40, h = 150;
    const cw = (W - 2 * margin - (cols - 1) * gutter) / cols;
    const colRects = Array.from({ length: cols }, (_, i) => `<rect x="${(margin + i * (cw + gutter)).toFixed(1)}" y="${top}" width="${cw.toFixed(1)}" height="${h}" fill="rgb(255 107 61 / 0.16)" stroke="rgb(229 83 42 / 0.5)"/>`).join('');
    const x2 = margin + cw + gutter;
    return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="A 12-column grid with margins, columns and gutters labelled" style="width:100%;height:auto;color:var(--text)">
      <rect x="0.5" y="${top - 12}" width="${W - 1}" height="${h + 24}" rx="8" fill="none" stroke="currentColor" stroke-opacity=".35"/>
      ${colRects}
      <rect x="${margin}" y="${top + 20}" width="${(cw * 8 + gutter * 7).toFixed(1)}" height="50" rx="5" fill="var(--bg-raised)" stroke="currentColor" stroke-opacity=".5"/>
      <text x="${margin + 12}" y="${top + 50}" font-size="12" fill="currentColor" font-family="Schibsted Grotesk">Content spans 8 columns + 7 gutters</text>
      <rect x="${(margin + 8 * (cw + gutter)).toFixed(1)}" y="${top + 20}" width="${(cw * 4 + gutter * 3).toFixed(1)}" height="50" rx="5" fill="var(--bg-raised)" stroke="currentColor" stroke-opacity=".5"/>
      <text x="${(margin + 8 * (cw + gutter) + 12).toFixed(1)}" y="${top + 50}" font-size="12" fill="currentColor" font-family="Schibsted Grotesk">Aside: 4 columns</text>
      <g font-family="JetBrains Mono" font-size="10" fill="var(--accent-text)">
        <line x1="0" y1="${top + h + 34}" x2="${margin}" y2="${top + h + 34}" stroke="currentColor"/><text x="2" y="${top + h + 48}">margin ${margin}</text>
        <line x1="${margin}" y1="${top + h + 22}" x2="${(margin + cw).toFixed(1)}" y2="${top + h + 22}" stroke="currentColor"/><text x="${margin}" y="${top + h + 18 - 4}">column ${cw.toFixed(1)}</text>
        <line x1="${(margin + cw).toFixed(1)}" y1="${top + h + 34}" x2="${x2.toFixed(1)}" y2="${top + h + 34}" stroke="currentColor"/><text x="${(margin + cw - 6).toFixed(1)}" y="${top + h + 48}">gutter ${gutter}</text>
        <text x="${W - 150}" y="${top - 18}">container ${W}px · 12 columns</text>
      </g></svg>`;
  },

  // Same content at three breakpoints.
  'grid-responsive'() {
    const frame = (label, cols, w, spans, note) => {
      const margin = cols === 4 ? 16 : 24, gutter = 16, H = 230;
      const cw = (w - 2 * margin - (cols - 1) * gutter) / cols;
      const colR = Array.from({ length: cols }, (_, i) => `<rect x="${(margin + i * (cw + gutter)).toFixed(1)}" y="0" width="${cw.toFixed(1)}" height="${H}" fill="rgb(255 107 61 / 0.12)"/>`).join('');
      let y = 12, c = 0; const blocks = [];
      spans.forEach(([span, hgt, name]) => {
        if (c + span > cols) { c = 0; y += blocks.at(-1).h + 10; }
        const x = margin + c * (cw + gutter), bw = span * cw + (span - 1) * gutter;
        blocks.push({ x, y, w: bw, h: hgt, name }); c += span; if (c >= cols) { c = 0; y += hgt + 10; }
      });
      const b = blocks.map((k) => `<rect x="${k.x.toFixed(1)}" y="${k.y}" width="${k.w.toFixed(1)}" height="${k.h}" rx="4" fill="var(--bg-raised)" stroke="currentColor" stroke-opacity=".45"/><text x="${(k.x + 6).toFixed(1)}" y="${k.y + 15}" font-size="9.5" fill="currentColor" font-family="JetBrains Mono">${k.name}</text>`).join('');
      return `<div><p class="row-label">${label}<span>${note}</span></p><svg viewBox="0 0 ${w} ${H}" style="width:100%;height:auto;color:var(--text);border:1px solid var(--rule);border-radius:6px;background:var(--bg)">${colR}${b}</svg></div>`;
    };
    const kpis = (n, span) => Array.from({ length: n }, (_, i) => [span, 44, 'KPI ' + (i + 1)]);
    return `<div style="display:grid;grid-template-columns:0.55fr 0.9fr 1.55fr;gap:16px;align-items:start">
      ${frame('Compact', 4, 220, [...kpis(4, 2), [4, 70, 'Chart']], '4 col · < 600')}
      ${frame('Medium', 8, 360, [...kpis(4, 2), [8, 80, 'Chart'], [8, 40, 'Table']], '8 col · 600–1199')}
      ${frame('Expanded', 12, 620, [...kpis(4, 3), [8, 110, 'Chart'], [4, 110, 'Activity'], [12, 36, 'Table']], '12 col · ≥ 1200')}
    </div>`;
  },

  // DTCG JSON, lightly syntax-coloured.
  dtcg() {
    // Collapse each token ({ $type, $value }) onto one line so the file reads like a token list.
    const json = JSON.stringify(dtcg, (k, v) => (v && typeof v === 'object' && '$type' in v ? '@@' + JSON.stringify(v).replace(/,/g, ', ').replace(/":/g, '": ') + '@@' : v), 2)
      .replace(/"@@(.*?)@@"/g, (_, j) => j.replace(/\\"/g, '"'))
      .replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/"(\$?[\w.-]+)":/g, '<span class="k">"$1"</span>:')
      .replace(/: "(\{[^"]+\})"/g, ': <span class="n">"$1"</span>')
      .replace(/: "([^"]+)"/g, ': <span class="s">"$1"</span>');
    return `<pre>${json}</pre>`;
  },
};

export function renderFigure(name, arg) {
  const fn = figures[name];
  if (!fn) throw new Error(`Unknown figure: ${name}`);
  return fn(arg);
}
export { palette, semantic, matrix, type, step };
